import { lazy } from 'react';
import { CalendarClock as IcCalendarClock, FileText as IcFileText, HardHat as IcHardHat, MapPinned as IcMapPinned, Package as IcPackage, PlugZap as IcPlugZap, Wrench as IcWrench } from 'lucide-react';
import { TabHub } from '@/components/pulse-ui';

/**
 * Field Operations — hub page for the Service Desk menu.
 *
 * Generated by the 2026-09-16 information-architecture pass, which collapsed
 * 6 sidebar rows into this one destination. Each page below keeps its
 * NAV_ITEMS entry marked `inHub: 'ServiceFieldCenter'`, so getSectionForPage() still
 * resolves it and every role gate behaves exactly as it did when each was its
 * own row. TabHub re-checks each tab with canRoleOpenPage() before drawing it.
 */
const FieldVisitScheduler = lazy(() => import('./FieldVisitScheduler'));
const ServiceEngineers = lazy(() => import('./ServiceEngineers'));
const InstallationRequests = lazy(() => import('./InstallationRequests'));
const CommissioningWorkflow = lazy(() => import('./CommissioningWorkflow'));
const DeliveryNote = lazy(() => import('./DeliveryNote'));
const ServiceStockManagement = lazy(() => import('./StockManagement'));

export const TABS = [
  { id: 'visits', label: 'Field Service', icon: IcCalendarClock, page: 'FieldVisitScheduler', Component: FieldVisitScheduler },
  { id: 'engineers', label: 'Service Engineers', icon: IcHardHat, page: 'ServiceEngineers', Component: ServiceEngineers },
  { id: 'installation', label: 'Installation', icon: IcWrench, page: 'InstallationRequests', Component: InstallationRequests },
  { id: 'commissioning', label: 'Commissioning', icon: IcPlugZap, page: 'CommissioningWorkflow', Component: CommissioningWorkflow },
  { id: 'delivery', label: 'Delivery Note', icon: IcFileText, page: 'DeliveryNote', Component: DeliveryNote },
  { id: 'spares', label: 'Spare Parts Stock', icon: IcPackage, page: 'ServiceStockManagement', Component: ServiceStockManagement },
];

export default function ServiceFieldCenter({ setPage }) {
  return (
    <TabHub
      icon={IcMapPinned}
      eyebrow="Service Desk"
      title="Field Operations"
      subtitle="Visit scheduling, engineers, installation, commissioning, delivery notes and spares"
      tabs={TABS}
      setPage={setPage}
    />
  );
}
